def find_web(path: str | None) -> pathlib.Path:
    candidates = []
    if path:
        p = pathlib.Path(path).expanduser().resolve()
        candidates.extend([p, p / 'web'])
    else:
        here = pathlib.Path(__file__).resolve().parent
        cwd = pathlib.Path.cwd().resolve()
        candidates.extend([cwd, cwd / 'web', here, here / 'web'])
    for p in candidates:
        if (p / 'src/game/roster.ts').is_file() and (p / 'public/icons').is_dir():
            return p
    raise SystemExit('Cannot find Fight Royale web folder. Run this script from web/ or pass its path.')


def main() -> None:
    root = find_web(sys.argv[1] if len(sys.argv) > 1 else None)
    stamp = dt.datetime.now().strftime('%Y%m%d-%H%M%S')
    backup_root = root / '.nythera-backups' / ('icons-' + stamp)
    print('Installing Nythera icons in:', root)
    updated = 0
    for name, encoded in ICONS.items():
        dest = root / 'public' / 'icons' / name
        payload = base64.b64decode(encoded)
        if dest.exists() and dest.read_bytes() == payload:
            print('  unchanged:', name)
            continue
        if dest.exists():
            backup = backup_root / name
            backup.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(dest, backup)
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_bytes(payload)
        print('  installed:', name)
        updated += 1
    print(f'Done: {updated} icon(s) updated. Original icons backed up if replaced.')
    print("Note: Aster.vrm is still Nythera's temporary 3D model; this changes icons only.")


if __name__ == '__main__':
    main()
